mapper.update:
update audit_task
set status = #{status},
    current_assignee = #{assignee},
    version = version + 1,
    update_time = #{updateTime}
where id = #{id}
  and status = #{expectedStatus}
  and version = #{version}

update audit_task
set deadline_at = #{deadline}
where id = #{id}
  and status in (0, 3)
  and (deadline_at is null or deadline_at > #{deadline})

update audit_task
set current_assignee = #{assignee},
    update_time = #{updateTime}
where id = #{id}
  and current_assignee is null
  and status = 0

update audit_task
set status = 0,
    current_assignee = null,
    version = version + 1,
    update_time = #{updateTime}
where id = #{id}
  and status = #{expectedStatus}
  and version = #{expectedVersion}
  and update_time is not null
  and update_time >= #{cutoff}

