select id from audit_task
where status = 0 and submitted_at < #{cutoff}
order by id asc limit 20

select id from audit_task
where status = 0 and deadline_at is not null and deadline_at < #{now}
order by id asc limit 20

select count(*) from audit_task
where submitter_id = #{submitterId}
  and source_type = 'report'
  and submitted_at >= #{since}
